import logging
import subprocess
import time
from collections.abc import Sequence
from typing import Any

from ttdl.browser import detect_browser
from ttdl.config import AppConfig
from ttdl.events import Reporter
from ttdl.termux import is_termux

log = logging.getLogger(__name__)


def export_netscape_cookies(cookies: Sequence[Any]) -> str:
    lines = [
        "# Netscape HTTP Cookie File",
        "# http://curl.haxx.se/rfc/cookie_spec.html",
        "# This file was automatically generated by ttdl.",
        "",
    ]
    for c in cookies:
        domain = str(c.get("domain", ""))
        include_sub = "TRUE" if domain.startswith(".") else "FALSE"
        path = str(c.get("path", "/"))
        secure = "TRUE" if c.get("secure", False) else "FALSE"
        expires = int(c.get("expires", 0))
        if expires <= 0:
            expires = int(time.time()) + 31536000
        name = str(c.get("name", ""))
        value = str(c.get("value", ""))
        lines.append(
            f"{domain}\t{include_sub}\t{path}\t{secure}\t{expires}\t{name}\t{value}"
        )

    return "\n".join(lines) + "\n"


class AuthManager:
    def __init__(self, config: AppConfig, reporter: Reporter) -> None:
        self.config = config
        self.reporter = reporter

    def login(self) -> int:
        try:
            from playwright.sync_api import sync_playwright
        except ImportError:
            self.reporter.error(
                "Playwright is not installed. Please install dependencies."
            )
            return 1

        if is_termux():
            from ttdl.termux import setup_termux

            setup_termux(self.reporter)

        self.reporter.info("AUTH_START target=tiktok_login")

        with sync_playwright() as p:
            context = None
            try:
                if is_termux():
                    self.reporter.debug("BROWSER_INIT mode=termux_cdp")
                    subprocess.run(
                        [
                            "adb",
                            "forward",
                            "tcp:9222",
                            "localabstract:chrome_devtools_remote",
                        ],
                        capture_output=True,
                        check=False,
                    )
                    subprocess.run(
                        [
                            "adb",
                            "shell",
                            "am",
                            "start",
                            "-n",
                            "com.android.chrome/com.google.android.apps.chrome.Main",
                            "-d",
                            "about:blank",
                        ],
                        capture_output=True,
                        check=False,
                    )

                    time.sleep(3)

                    try:
                        browser = p.chromium.connect_over_cdp("http://localhost:9222")
                    except Exception as e:
                        self.reporter.error("CDP_FAIL %s", str(e))
                        return 1

                    context = browser.contexts[0]
                    page = context.pages[0] if context.pages else context.new_page()
                else:
                    browser_name, default_path = detect_browser()
                    browser_path = self.config.browser_executable or default_path
                    session_dir = self.config.session_dir / browser_name
                    session_dir.mkdir(parents=True, exist_ok=True)

                    self.reporter.debug(
                        "BROWSER_INIT browser=%s session=%s",
                        browser_name,
                        session_dir.name,
                    )
                    context = p.chromium.launch_persistent_context(
                        user_data_dir=str(session_dir),
                        executable_path=browser_path,
                        headless=False,
                        args=[
                            "--disable-blink-features=AutomationControlled",
                            "--start-maximized",
                            "--no-first-run",
                        ],
                        ignore_default_args=["--enable-automation"],
                        no_viewport=True,
                    )
                    page = context.pages[0] if context.pages else context.new_page()

                page.goto("https://www.tiktok.com/login", wait_until="domcontentloaded")
                self.reporter.info(
                    "AUTH_WAIT Please log in to your TikTok account in the browser"
                )
                self.reporter.set_status(
                    "Waiting for browser login... (Press Ctrl+C to cancel)"
                )
                self.reporter.debug(
                    "AUTH_POLL Waiting for authentication... Press Ctrl+C to cancel"
                )

                timeout_seconds = 300
                start_time = time.time()
                authenticated = False

                while time.time() - start_time < timeout_seconds:
                    time.sleep(1.5)
                    try:
                        if page.is_closed():
                            break

                        cookies = context.cookies()
                        for c in cookies:
                            c_name = c.get("name", "")
                            c_val = c.get("value", "")
                            if c_name in ("sessionid_ss", "sessionid") and c_val:
                                authenticated = True
                                break

                        if authenticated:
                            break
                    except Exception:
                        break

                self.reporter.clear_status()
                if not authenticated:
                    self.reporter.error(
                        "AUTH_TIMEOUT Login was not completed or timed out"
                    )
                    return 1

                # Export and save cookies
                cookies = context.cookies()
                cookie_content = export_netscape_cookies(cookies)

                self.config.config_dir.mkdir(parents=True, exist_ok=True)
                out_path = self.config.config_dir / "cookies.txt"
                out_path.write_text(cookie_content, encoding="utf-8")

                self.reporter.success("AUTH_SUCCESS Cookies saved to %s", out_path)
                return 0

            except KeyboardInterrupt:
                self.reporter.clear_status()
                self.reporter.warning("AUTH_CANCEL Login cancelled by user")
                return 1
            except Exception as e:
                self.reporter.clear_status()
                self.reporter.error("AUTH_FAIL %s", str(e))
                return 1
            finally:
                if context:
                    try:
                        context.close()
                    except Exception:
                        pass
